const scene = String(msg.payload).trim().toLowerCase();

const outputs = [null, null, null, null];

switch (scene) {
    case "tv":
        outputs[0] = { payload: "on" };
        break;

    case "sleep":
        outputs[1] = { payload: "on" };
        break;

    case "all_on":
        outputs[2] = { payload: "on" };
        break;

    case "all_off":
        outputs[3] = { payload: "on" };
        break;

    default:
        node.warn(`Unknown light scene: ${scene}`);
        return null;
}

// Preserve only explicit app scene provenance. Operational payloads unchanged.
if (msg.retain !== true) {
 const sequence=(context.get('semantic_scene_seq')||0)+1;
 context.set('semantic_scene_seq',sequence);
 for(const out of outputs) if(out) out._semantic_scene={
  actor:'utente',origin:'app_interface',scene,
  command_id:node.id+':'+Date.now()+':'+sequence,attribution:'interface_contract'};
}
return outputs;

const c = msg._semantic_command;
const rm = msg.payload;
let telemetry = null;
// RM reports OK after invoking sendData, without waiting for a lamp acknowledgment.
if (c && c.schema === 'domopi.semantic_command.v1' &&
    c.entity_id === 'lights.libreria.power' && ['utente','automazione'].includes(c.actor) &&
    ['dispatched','source_selected'].includes(c.stage) && typeof c.command_id === 'string' &&
    c.requested_state === true && rm && rm.status === 'OK') {
    const e = {schema:'domopi.semantic_command.v1',entity_id:c.entity_id,
        command_id:c.command_id,actor:c.actor,origin:c.origin,scene:c.scene||null,
        attribution:c.attribution,requested_state:c.requested_state,
        source_retained:c.source_retained===true,
        stage:'send_invoked',observed_at_ms:Date.now(),
        evidence:'rm_output_after_sendData',execution_confirmed:false,
        physical_confirmation:false,publisher_authenticated:false};
    telemetry = [
        {topic:'zara/interface/semantic/v1/rm_receipts/'+c.entity_id+'/stat',
         payload:JSON.stringify(e),qos:1,retain:true},
        {topic:'zara/interface/semantic/v1/events',
         payload:JSON.stringify({...e,schema:'domopi.semantic_event.v1',
             event_id:c.command_id+':rm',kind:'rm_send_invoked'}),qos:1,retain:false}
    ];
}
delete msg._semantic_command;
msg.payload = 'on';
return [msg, telemetry];

